<?php
return function (Router $r) {
    $r->get('/desktop/panel/data',function () { $today=date('Y-m-d'); $tables=InsightsService::tables(); $prefs=desktop_panel_preferences(); $items=[]; if ($prefs['showTasks']&&in_array('tasks',$tables,true)) foreach (Db::all("SELECT id,title,due,'Task' kind FROM tasks WHERE status='open' AND due=? ORDER BY title LIMIT 12",[$today]) as $item) $items[]=$item; if ($prefs['showAssignments']&&in_array('assignments',$tables,true)) foreach (Db::all("SELECT a.id,a.title,a.due_date due,'Assignment' kind FROM assignments a WHERE a.status!='done' AND a.due_date=? ORDER BY a.title LIMIT 12",[$today]) as $item) $items[]=$item; if ($prefs['showExams']&&in_array('exams',$tables,true)) foreach (Db::all('SELECT e.id,COALESCE(m.name,\'Exam\') title,e.date due,\'Exam\' kind FROM exams e LEFT JOIN uni_modules m ON m.id=e.module_id WHERE e.date=? ORDER BY title LIMIT 12',[$today]) as $item) $items[]=$item; if ($prefs['showLectures']&&in_array('planner_appointments',$tables,true)) foreach (Db::all("SELECT p.id,p.title,p.starts_at due,CASE WHEN u.id IS NULL THEN 'Event' ELSE 'Lecture' END kind FROM planner_appointments p LEFT JOIN uni_calendar_events u ON u.appointment_id=p.id WHERE p.status='scheduled' AND date(p.starts_at)=? ORDER BY p.starts_at LIMIT 12",[$today]) as $item) $items[]=$item; usort($items,fn($a,$b)=>strcmp((string)$a['due'],(string)$b['due'])); $todos=$prefs['showTodos']&&in_array('tasks',$tables,true)?Db::all("SELECT id,title,due FROM tasks WHERE source='desktop-panel-todo' AND status='open' ORDER BY id DESC LIMIT 20"):[]; $notes=$prefs['showNotes']&&in_array('desktop_panel_notes',$tables,true)?Db::all('SELECT id,title,body,created_at FROM desktop_panel_notes ORDER BY id DESC LIMIT 6'):[]; header('Content-Type: application/json; charset=utf-8'); header('Cache-Control: no-store'); return json_encode(['today'=>$today,'items'=>array_slice($items,0,24),'todos'=>$todos,'notes'=>$notes,'preferences'=>$prefs],JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE); });
    $r->get('/desktop/panel',function () { header('Content-Type: text/html; charset=utf-8'); header('Cache-Control: no-store'); return View::render(__DIR__.'/views/desktop-panel.php',[],''); });
    $r->post('/desktop/panel/add',function () { $kind=$_POST['kind']??''; if(!is_string($kind)||!in_array($kind,['task','todo','note'],true)) throw new InvalidArgumentException('Choose a task, to-do or note.'); $title=text_input('title',160); $body=text_input('body',3000,false); $due=$_POST['due']??''; if(!is_string($due)) throw new InvalidArgumentException('Choose a valid date.'); $due=$due===''?null:valid_date($due); if($kind==='note'){Db::run('INSERT INTO desktop_panel_notes(title,body) VALUES (?,?)',[$title,$body]);return json_encode(['ok'=>true],JSON_THROW_ON_ERROR);} Db::run('INSERT INTO tasks(title,due,status,source) VALUES (?,?,\'open\',?)',[$title,$due,$kind==='todo'?'desktop-panel-todo':'desktop-panel']); return json_encode(['ok'=>true],JSON_THROW_ON_ERROR); });
    $r->post('/desktop/panel/todo/{id}/complete',function ($p) { if(!ctype_digit($p['id'])) throw new InvalidArgumentException('Invalid to-do.'); $todo=Db::one("SELECT id FROM tasks WHERE id=? AND source='desktop-panel-todo' AND status='open'",[(int)$p['id']]); if(!$todo) throw new InvalidArgumentException('To-do not found.'); Db::run("UPDATE tasks SET status='done' WHERE id=?",[(int)$p['id']]); return json_encode(['ok'=>true],JSON_THROW_ON_ERROR); });
    $r->post('/desktop/panel/note/{id}/delete',function ($p) { if(!ctype_digit($p['id'])) throw new InvalidArgumentException('Invalid note.'); Db::run('DELETE FROM desktop_panel_notes WHERE id=?',[(int)$p['id']]); return json_encode(['ok'=>true],JSON_THROW_ON_ERROR); });
    $r->post('/desktop/panel/preferences',function () { $keys=['showTasks','showTodos','showAssignments','showExams','showLectures','showNotes','autoHide']; $prefs=[];foreach($keys as $key)$prefs[$key]=isset($_POST[$key])&&$_POST[$key]==='1';Db::set('desktop_panel_preferences',json_encode($prefs,JSON_THROW_ON_ERROR));header('Content-Type: application/json; charset=utf-8');return json_encode(['ok'=>true,'preferences'=>$prefs],JSON_THROW_ON_ERROR); });
    $r->get('/insights',function () { $month=$_GET['month'] ?? date('Y-m'); if (!is_string($month)) throw new InvalidArgumentException('Choose a valid month.'); $month=valid_month($month); return View::render(__DIR__.'/views/index.php',['title'=>'Review & insights','month'=>$month,'summary'=>InsightsService::monthly($month),'review'=>Db::one('SELECT * FROM monthly_life_reviews WHERE month=?',[$month]),'alerts'=>InsightsService::alerts()]); });
    $r->get('/insights/alerts',function () { $alerts=InsightsService::alerts(); header('Content-Type: application/json'); return json_encode(['enabled'=>Db::setting('notifications_enabled')==='1','csrf'=>$_SESSION['csrf'],'unreadCount'=>count(array_filter($alerts,fn($item)=>empty($item['read']))),'alerts'=>$alerts],JSON_THROW_ON_ERROR); });
    $r->post('/insights/alerts/{id}/read',function ($p) { InsightsService::markRead($p['id']); header('Content-Type: application/json'); return '{"ok":true}'; });
    $r->post('/insights/alerts/read-all',function () { InsightsService::markAllRead(); header('Content-Type: application/json'); return '{"ok":true}'; });
    $r->post('/insights/alerts/{id}/dismiss',function ($p) { if (!preg_match('/^[a-f0-9]{64}$/',$p['id'])) throw new InvalidArgumentException('Invalid notification.'); Db::run('INSERT OR IGNORE INTO notification_dismissals(key) VALUES (?)',[$p['id']]); return redirect('/insights#alerts','Reminder dismissed for today.'); });
    $r->post('/insights/notifications',function () { Db::set('notifications_enabled',isset($_POST['enabled']) ? '1' : '0'); return redirect('/insights#alerts','Notification preferences saved.'); });
    $r->post('/insights/review',function () { $month=valid_month(text_input('month')); InsightsService::review($month,text_input('wins',5000,false),text_input('lessons',5000,false),text_input('focus',2000,false),int_range($_POST['score'] ?? '',1,10)); return redirect('/insights?month='.$month,'Monthly review saved.'); });
};

function desktop_panel_preferences(): array { $defaults=['showTasks'=>true,'showTodos'=>true,'showAssignments'=>true,'showExams'=>true,'showLectures'=>true,'showNotes'=>true,'autoHide'=>true];$saved=json_decode(Db::setting('desktop_panel_preferences',''),true);return is_array($saved)?array_replace($defaults,array_intersect_key($saved,$defaults)):$defaults; }
function desktop_panel_preference(string $name,string $label): string { return '<label><input type="checkbox" data-panel-pref="'.e($name).'">'.e($label).'</label>'; }
